// Calculate lead score based on interactions and profile
const input = $input.first().json;
const leadId = input.record?.lead_id || input.lead_id;

if (!leadId) return [];

// This will be populated by the Supabase queries below
return [{ json: { lead_id: leadId, mode: 'score' } }];

// SCORING ENGINE
// Fetches lead + interactions and calculates score
// NOTE: In production, replace with actual Supabase queries

const lead = $input.first().json;

// Default scoring weights (should come from ICP criteria)
const WEIGHTS = {
  interaction: {
    email_opened: 5,
    email_clicked: 15,
    email_replied: 30,
    multi_open_bonus: 2,
    multi_email_bonus: 10
  },
  profile: {
    has_website: 5,
    company_medium_plus: 10,
    role_decisor: 15,
    has_linkedin: 5,
    source_linkedin: 10,
    source_maps_oab: 5
  },
  hot_threshold: 50
};

// Calculate interaction score
// (In production, count from interactions table)
let interactionScore = 0;
interactionScore += (lead.emails_opened || 0) * WEIGHTS.interaction.email_opened;
interactionScore += (lead.emails_clicked || 0) * WEIGHTS.interaction.email_clicked;
interactionScore += (lead.emails_replied || 0) * WEIGHTS.interaction.email_replied;
if ((lead.emails_opened || 0) > 1) {
  interactionScore += WEIGHTS.interaction.multi_email_bonus;
}

// Calculate profile score
let profileScore = 0;
if (lead.company_website) profileScore += WEIGHTS.profile.has_website;
if (['medium', 'large'].includes(lead.company_size)) profileScore += WEIGHTS.profile.company_medium_plus;
if (lead.role && /socio|diretor|partner/i.test(lead.role)) profileScore += WEIGHTS.profile.role_decisor;
if (lead.linkedin_url) profileScore += WEIGHTS.profile.has_linkedin;
if (lead.source === 'linkedin') profileScore += WEIGHTS.profile.source_linkedin;
if (['google_maps', 'oab_directory'].includes(lead.source)) profileScore += WEIGHTS.profile.source_maps_oab;

const totalScore = Math.max(0, interactionScore + profileScore);
const previousScore = lead.lead_score || 0;
const isHot = totalScore >= WEIGHTS.hot_threshold && previousScore < WEIGHTS.hot_threshold;

return [{
  json: {
    lead_id: lead.id,
    previous_score: previousScore,
    new_score: totalScore,
    interaction_score: interactionScore,
    profile_score: profileScore,
    is_hot: isHot,
    threshold: WEIGHTS.hot_threshold
  }
}];

// Apply weekly decay to all leads
// Leads with no interaction in 14+ days lose 10% per week

// NOTE: In production, query all leads and their last interaction date
// For each lead where daysSinceLastInteraction >= 14:
//   new_score = Math.max(0, Math.floor(current_score * 0.9))

return [{
  json: {
    mode: 'decay',
    note: 'CONFIGURE: Add Supabase query to fetch all leads, calculate decay, batch update',
    decay_formula: 'new_score = max(0, floor(current_score * 0.9))',
    condition: 'last interaction >= 14 days ago'
  }
}];

